        _partition_priority(partition_value),
        state.sciscinet_count if partition_value == KTP_PARTITION_SCISCINET_VALUE else 0,
        sciscinet_tie_sort if partition_value == KTP_PARTITION_SCISCINET_VALUE else 0,
